#include<iostream>
#include<vector>
#include<string>
#include <utility> 
#include <sstream>
#include<algorithm> 
using namespace std;
​
int main() {
    int n;
    cin >> n;
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        cin >> ans[i];
    }

    sort(ans.begin(), ans.end());
    // 中位数定理 中位数的点距离其它位置和是最小的
    // 奇数找中间点
    if (n % 2) {
        cout << ans[n / 2];
    // 偶数时也取中位数，结果要求较小值    
    } else {
        cout << ans[n / 2 - 1];
    }
​
    return 0;
}

