#include <stdio.h>
#include <stdlib.h>
​
// 比较函数，用于 qsort 排序
int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
​
int main() {
    int n;
    scanf("%d", &n);
​
    int ans[1000]; 
    for (int i = 0; i < n; i++) {
        scanf("%d", &ans[i]);
    }
​
    // 排序
    qsort(ans, n, sizeof(int), compare);
​
    // 中位数定理：中位数的点距离其它位置和是最小的
    // 奇数找中间点
    if (n % 2 == 1) {
        printf("%d\n", ans[n / 2]);
    // 偶数时也取中位数，结果要求较小值
    } else {
        printf("%d\n", ans[n / 2 - 1]);
    }
​
    return 0;
}
