package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
func main() {
    // 读取输入
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text())
​
    scanner.Scan()
    numsStr := strings.Split(scanner.Text(), " ")
    ans := make([]int, n)
​
    for i, str := range numsStr {
        ans[i], _ = strconv.Atoi(str)
    }
​
    // 排序
    sort.Ints(ans)
​
    // 选择中位数（偶数时选较小的）
    if n%2 == 1 {
        fmt.Println(ans[n/2])
    } else {
        fmt.Println(ans[n/2-1])
    }
}
